// swift-format-ignore-file

// Generates the locale tables behind I18nextFormatters by asking the ICU that ships with this Mac (through
// JavaScriptCore's `Intl`) for the patterns Foundation can't hand out: what `Intl.ListFormat` joins `unit` lists with.
//
//   swift Scripts/generate-formatter-data.swift [output directory]
//
// The output directory defaults to Sources/I18nextFormatters. macOS only. ICU's data is Unicode CLDR's, so the
// generated files carry the Unicode license; the CLDR release is whichever this macOS version ships (recorded in
// the file). Locales whose tables equal what they would inherit by dropping their last subtag are left out; the
// runtime falls back the same way.

import Foundation
import JavaScriptCore

let arguments = CommandLine.arguments
let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
let outputDirectory =
    arguments.count > 1
    ? URL(fileURLWithPath: arguments[1]) : root.appendingPathComponent("Sources/I18nextFormatters")

let context = JSContext()!
context.exceptionHandler = { _, exception in
    FileHandle.standardError.write(Data("JS error: \(exception?.toString() ?? "?")\n".utf8))
    exit(1)
}

/// BCP 47 tags for every locale this system knows, regions included, with no variants or extensions.
let tags: [String] = {
    var seen = Set<String>()
    for identifier in Locale.availableIdentifiers {
        let tag = identifier.replacingOccurrences(of: "_", with: "-")
        guard !tag.contains("@"), tag.split(separator: "-").count <= 3, tag != "root" else { continue }
        seen.insert(tag)
    }
    return seen.sorted()
}()
context.setObject(tags, forKeyedSubscript: "tags" as NSString)

/// Keeps a locale only when its table differs from what dropping subtags would give.
func parent(_ tag: String) -> String? {
    tag.contains("-") ? String(tag[..<tag.lastIndex(of: "-")!]) : nil
}

func dedupe<Value: Equatable>(_ tables: [String: Value]) -> [String: Value] {
    var kept: [String: Value] = [:]
    for tag in tables.keys.sorted(by: { ($0.filter { $0 == "-" }.count, $0) < ($1.filter { $0 == "-" }.count, $1) }) {
        var inherited: Value?
        var up = parent(tag)
        while let candidate = up {
            if let value = kept[candidate] {
                inherited = value
                break
            }
            up = parent(candidate)
        }
        if inherited == nil || inherited! != tables[tag]! { kept[tag] = tables[tag]! }
    }
    return kept
}

func literal(_ text: String) -> String {
    let data = try! JSONSerialization.data(withJSONObject: [text], options: [.fragmentsAllowed])
    let array = String(decoding: data, as: UTF8.self)
    return String(array.dropFirst().dropLast()).replacingOccurrences(of: "\\/", with: "/")
}

let header = """
// Copyright © 1991-2025 Unicode, Inc.
// SPDX-License-Identifier: Unicode-3.0
//
// Derived from the Unicode CLDR data, as shipped in the ICU of \(ProcessInfo.processInfo.operatingSystemVersionString).
// See https://www.unicode.org/license.txt for the terms of use.
//
// GENERATED by Scripts/generate-formatter-data.swift. Do not edit.
// swift-format-ignore-file


"""

// MARK: - List patterns

/// For long, short and narrow: the pattern joining the first item to the rest (`start`), two inner items
/// (`middle`), the last two (`end`), and a list of exactly two (`2`).
let listProbe = """
(function () {
    var strip = function (s) { return s.replace(/[\\u2068\\u2069]/g, ''); };
    var result = {};
    tags.forEach(function (tag) {
        try {
            if (Intl.ListFormat.supportedLocalesOf([tag]).length === 0) return;
            var rows = [];
            ['long', 'short', 'narrow'].forEach(function (width) {
                var f = new Intl.ListFormat(tag, { type: 'unit', style: width });
                var four = strip(f.format(['A', 'B', 'C', 'D']));
                var two = strip(f.format(['A', 'B']));
                var m = /^(.*)A(.*)B(.*)C(.*)D(.*)$/.exec(four);
                var p = /^(.*)A(.*)B(.*)$/.exec(two);
                if (!m || !p || m[1] !== '' || m[5] !== '' || p[1] !== '' || p[3] !== '') throw new Error('unexpected shape for ' + tag + ': ' + four);
                rows.push('{0}' + m[2] + '{1}', '{0}' + m[3] + '{1}', '{0}' + m[4] + '{1}', '{0}' + p[2] + '{1}');
            });
            result[tag] = rows;
        } catch (e) { if (String(e).indexOf('unexpected') >= 0) throw e; }
    });
    return JSON.stringify(result);
})()
"""
let listTables = try! JSONDecoder().decode(
    [String: [String]].self,
    from: Data(context.evaluateScript(listProbe)!.toString()!.utf8)
)
let lists = dedupe(listTables)

var listSource = header + "enum CLDRListPatternData {\n"
listSource += "    /// `Intl.ListFormat` with `type: \"unit\"`: for long, short and narrow, the patterns of `start`, `middle`,\n"
listSource += "    /// `end` (three or more items) and of exactly two items.\n"
listSource += "    static let unit: [String: [String]] = [\n"
for tag in lists.keys.sorted() {
    listSource += "        \(literal(tag)): [\n"
    for row in stride(from: 0, to: 12, by: 4) {
        listSource += "            " + lists[tag]![row..<row + 4].map(literal).joined(separator: ", ") + ",\n"
    }
    listSource += "        ],\n"
}
listSource += "    ]\n}\n"
try! listSource.write(
    to: outputDirectory.appendingPathComponent("CLDRListPatternData.swift"),
    atomically: true,
    encoding: .utf8
)
print("CLDRListPatternData.swift: \(lists.count) of \(listTables.count) locales")
